<?php require_once '../functions.php'; require_admin(); $title='Admin Dashboard';$stats=[];$stats['produk']=$koneksi->query('SELECT COUNT(*) c FROM produk')->fetch_assoc()['c'];$stats['user']=$koneksi->query("SELECT COUNT(*) c FROM users WHERE role='user'")->fetch_assoc()['c'];$stats['pesanan']=$koneksi->query('SELECT COUNT(*) c FROM pesanan')->fetch_assoc()['c'];$stats['omzet']=$koneksi->query("SELECT COALESCE(SUM(total),0) c FROM pesanan WHERE status IN ('paid','processing','shipped','completed')")->fetch_assoc()['c'];$recent=$koneksi->query('SELECT p.id_pesanan,p.total,p.status,p.created_at,u.nama FROM pesanan p JOIN users u ON u.id_user=p.id_user ORDER BY p.id_pesanan DESC LIMIT 8');include 'header.php'; ?>
<div class="container"><div class="section-head"><div><span class="pill">ADMIN PANEL</span><h1>Dashboard</h1><p class="muted">Pantau toko dan aktivitas transaksi.</p></div><a class="btn" href="laporan.php">Buka Laporan</a></div><div class="stats"><div><small>Total Produk</small><b><?=$stats['produk']?></b></div><div><small>User</small><b><?=$stats['user']?></b></div><div><small>Pesanan</small><b><?=$stats['pesanan']?></b></div><div><small>Omzet</small><b><?=rupiah($stats['omzet'])?></b></div></div><div class="panel"><div class="section-head"><h2>Pesanan Terbaru</h2><a href="pesanan.php">Kelola semua →</a></div><div class="table-wrap"><table><tr><th>ID</th><th>Pelanggan</th><th>Total</th><th>Status</th><th>Tanggal</th></tr><?php while($r=$recent->fetch_assoc()):?><tr><td>#<?=$r['id_pesanan']?></td><td><?=e($r['nama'])?></td><td><?=rupiah($r['total'])?></td><td><?=e(order_status_label($r['status']))?></td><td><?=e($r['created_at'])?></td></tr><?php endwhile;?></table></div></div></div><?php include '../footer.php'; ?>
